//! The Effects store: the continuous effects resolved spells and abilities created (plan K4;
//! the crate's contract, "Stores").
//!
//! [CR 611.2](https://yawgatog.com/resources/magic-rules/#R6112): "A continuous effect may
//! be generated by the resolution of a spell or ability." Each is one entry: what it
//! affects, what it does (its payload, a resolved kernel type that names no word of a card
//! left to settle), how long it lasts, the card it came from and its timestamp. The rules
//! start one with [`State::start_effect`] and read them by kind: the layers ask for
//! [`State::layer_effects`], a zone change for [`State::move_replacements`]. A kind with
//! nothing live costs its reader one AND.
//!
//! Built so far: an object (by-w8gv.7.2), a player (by-w8gv.7.3) and a locked-in set of
//! objects ([`sets`], by-w8gv.7.5) as the affected side, and the layer change, the
//! zone-change replacement, the rule change, the permission to cast and the cost change
//! (by-w8gv.7.4) as payloads. The game as a side is designed in the contract and built with
//! its first user.
//!
//! [`State::rule_applies`] is the one question about a rule change, whether a static
//! ability or one of these effects makes it.

use beryl_card::{GrantIx, Keywords, Layer, Modification, Rule, Rules, Subtype, Types};

use crate::bitboard::Bitboard;
use crate::fixed::Full;
use crate::ids::{CardId, Seat};
use crate::layout::{Layout, Queue, Small, Table};
use crate::object::ObjectRef;
use crate::observation::Observation;
use crate::state::State;
use crate::store::{Duration, Ended};
use crate::table::GameTable;

mod sets;
mod store;

use sets::Sets;
pub use sets::{LockedIn, SETS};

/// The continuous effects a [`Small`] game holds at once. One past it stalls the game into
/// [`crate::Large`], whose store grows.
pub const EFFECTS: usize = 64;

/// What a continuous effect affects.
///
/// An object is named by one incarnation of its slot, so the effect ends with the object
/// ([CR 400.7](https://yawgatog.com/resources/magic-rules/#R4007)). The fields are the
/// variant's own rather than an [`ObjectRef`] so that every side (a player, a locked-in
/// set, and the game to come) shares its four bytes in [`Small`].
///
/// A player is affected by a rule change alone: a layer changes a permanent and a zone
/// change is an object's. A set is affected by a layer change alone: only a change to
/// characteristics or control locks in what it affects (CR 611.2c), and nothing else that
/// the cards do is one effect on several objects.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Affects<L: Layout = Small> {
    /// One object, as it was when the effect began
    /// ([CR 611.2c](https://yawgatog.com/resources/magic-rules/#R6112c)): "the set of objects
    /// it affects is determined when that continuous effect begins. After that point, the set
    /// won't change."
    Object { slot: L::Slot, incarnation: u16 },
    /// One player: "you may", "target player can't".
    Player(Seat),
    /// Several permanents, those that were there as the effect began and have not left
    /// since ([CR 611.2c](https://yawgatog.com/resources/magic-rules/#R6112c)): "After that
    /// point, the set won't change." [`State::locked_in`] reads them.
    Set(LockedIn<L>),
}

impl<L: Layout> Affects<L> {
    /// The object `r` names.
    #[inline]
    pub fn object(r: ObjectRef<L>) -> Affects<L> {
        Affects::Object {
            slot: r.slot,
            incarnation: r.incarnation,
        }
    }

    /// The object it affects, if it affects one and no more.
    #[inline]
    pub fn as_object(self) -> Option<ObjectRef<L>> {
        match self {
            Affects::Object { slot, incarnation } => Some(ObjectRef { slot, incarnation }),
            Affects::Player(_) | Affects::Set(_) => None,
        }
    }
}

impl<L: Layout> From<ObjectRef<L>> for Affects<L> {
    #[inline]
    fn from(object: ObjectRef<L>) -> Affects<L> {
        Affects::object(object)
    }
}

/// A change to a permanent in a layer, with every word of the card that wrote it settled:
/// the resolved form of `beryl_card`'s [`Modification`], as [`Duration`] is of its
/// `Duration`. The layer it applies in follows from the change
/// ([CR 613.1](https://yawgatog.com/resources/magic-rules/#R6131)).
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum LayerChange {
    /// Layer 2: this player controls it.
    Control(Seat),
    /// Layer 4: "becomes [types] in addition to its other types".
    AddTypes(Types),
    /// Layer 4: "isn't a [type]".
    RemoveTypes(Types),
    /// Layer 4: "is a [types] and loses all other card types".
    SetTypes(Types),
    /// Layer 4: "is a [subtype]".
    AddSubtype(Subtype),
    /// Layer 6: "gains [keywords]".
    AddKeywords(Keywords),
    /// Layer 6: "has [ability]", the ability at this index of the effect source's front
    /// face's grants.
    Grant(GrantIx),
    /// Layer 7a: "power is equal to the number of creatures you control", read of its
    /// controller as the layer applies.
    PowerIsCreaturesYouControl,
    /// Layer 7c: "gets +X/+Y".
    ModifyPt(i8, i8),
}

impl LayerChange {
    /// What `modification` is for an ability whose controller is `you`: "gain control"
    /// names that player.
    #[inline]
    pub fn resolve(modification: Modification, you: Seat) -> LayerChange {
        match modification {
            Modification::Control => LayerChange::Control(you),
            Modification::AddTypes(types) => LayerChange::AddTypes(types),
            Modification::RemoveTypes(types) => LayerChange::RemoveTypes(types),
            Modification::SetTypes(types) => LayerChange::SetTypes(types),
            Modification::AddSubtype(subtype) => LayerChange::AddSubtype(subtype),
            Modification::AddKeywords(keywords) => LayerChange::AddKeywords(keywords),
            Modification::Grant(grant) => LayerChange::Grant(grant),
            Modification::PowerIsCreaturesYouControl => LayerChange::PowerIsCreaturesYouControl,
            Modification::ModifyPt(power, toughness) => LayerChange::ModifyPt(power, toughness),
        }
    }

    /// The layer or sublayer it applies in
    /// ([CR 613.1](https://yawgatog.com/resources/magic-rules/#R6131),
    /// [CR 613.4](https://yawgatog.com/resources/magic-rules/#R6134)).
    #[inline]
    pub fn layer(self) -> Layer {
        match self {
            LayerChange::Control(_) => Layer::Control,
            LayerChange::AddTypes(_)
            | LayerChange::RemoveTypes(_)
            | LayerChange::SetTypes(_)
            | LayerChange::AddSubtype(_) => Layer::Type,
            LayerChange::AddKeywords(_) | LayerChange::Grant(_) => Layer::Ability,
            LayerChange::PowerIsCreaturesYouControl => Layer::PtDefining,
            LayerChange::ModifyPt(..) => Layer::PtModifying,
        }
    }
}

/// A replacement of where an object goes
/// ([CR 614.1a](https://yawgatog.com/resources/magic-rules/#R6141a)): "Effects that use the
/// word 'instead' are replacement effects."
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum MoveReplacement {
    /// "If it would be put into a graveyard, exile it instead."
    ExileInsteadOfGraveyard,
    /// What paying a flashback cost does to the spell
    /// ([CR 702.34a](https://yawgatog.com/resources/magic-rules/#R70234a)): "If the flashback
    /// cost was paid, exile this card instead of putting it anywhere else any time it would
    /// leave the stack."
    Flashback,
}

/// A permission to cast the affected card from the zone it is in, with the terms a spell
/// cast under it is cast on
/// ([CR 601.3](https://yawgatog.com/resources/magic-rules/#R6013)): "A player can begin to
/// cast a spell only if a rule or effect allows that player to cast it". It is an entry on
/// one incarnation of the card, so it ends when the card leaves that zone
/// ([CR 400.7](https://yawgatog.com/resources/magic-rules/#R4007)), whatever its duration.
///
/// The terms are about the spell, which is a new object: as it is cast the rules start
/// them on it, a [`Payload::Cost`] for the increase and a [`Payload::Move`] for the
/// replacement.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Permission {
    /// Who may cast the card, which need not be its owner.
    pub player: Seat,
    /// Generic mana the spell costs more, as in "A spell cast this way costs {2} more to
    /// cast."
    pub increase: u8,
    /// Where the spell goes instead as it leaves the stack: "If that spell would be put
    /// into your graveyard, exile it instead.", or flashback's own.
    pub replacement: Option<MoveReplacement>,
}

impl Permission {
    /// Whether the card has flashback by it, its flashback cost the card's mana cost
    /// ([CR 702.34a](https://yawgatog.com/resources/magic-rules/#R70234a)): "'Flashback
    /// [cost]' means 'You may cast this card from your graveyard if the resulting spell is an
    /// instant or sorcery spell by paying [cost] rather than paying its mana cost'". Paying it
    /// is an alternative cost, so no other can be chosen with it.
    #[inline]
    pub fn is_flashback(self) -> bool {
        self.replacement == Some(MoveReplacement::Flashback)
    }
}

/// A change to what the affected spell costs, applied as its total cost is determined
/// ([CR 601.2f](https://yawgatog.com/resources/magic-rules/#R6012f)): "The total cost is the
/// mana cost or alternative cost (as determined in rule 601.2b), plus all additional costs
/// and cost increases, and minus all cost reductions."
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum CostChange {
    /// It costs this much generic mana more.
    Increase(u8),
}

/// A permission to cast in force: the card it is about, its terms, and the card whose
/// spell or ability granted it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Permitted<L: Layout = Small> {
    pub card: ObjectRef<L>,
    pub terms: Permission,
    pub source: L::Card,
}

/// What a continuous effect does.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Payload {
    /// Changes the affected permanent in a layer (architecture §9).
    Layer(LayerChange),
    /// Replaces a zone change of the affected object.
    Move(MoveReplacement),
    /// Changes a rule of the game for what it affects
    /// ([CR 613.11](https://yawgatog.com/resources/magic-rules/#R61311)): "Some continuous
    /// effects affect game rules rather than objects." The rule is the vocabulary's own:
    /// it names no player, and the affected side is who it applies to.
    Rule(Rule),
    /// Lets a player cast the affected card from the zone it is in.
    Cast(Permission),
    /// Changes what the affected spell costs.
    Cost(CostChange),
}

impl Payload {
    /// The bit of its kind in a store's [`Kinds`].
    #[inline]
    fn kind(self) -> u16 {
        match self {
            Payload::Layer(_) => Kinds::LAYER,
            Payload::Move(_) => Kinds::MOVE,
            Payload::Rule(_) => Kinds::RULE,
            Payload::Cast(_) => Kinds::CAST,
            Payload::Cost(_) => Kinds::COST,
        }
    }
}

/// The kinds of payload among a store's entries: its index by kind, so that a reader of a
/// kind with nothing live stops at one AND.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
struct Kinds(u16);

impl Kinds {
    const LAYER: u16 = 1 << 0;
    const MOVE: u16 = 1 << 1;
    const RULE: u16 = 1 << 2;
    const CAST: u16 = 1 << 3;
    const COST: u16 = 1 << 4;
}

/// A continuous effect from a resolved spell or ability
/// ([CR 611.2](https://yawgatog.com/resources/magic-rules/#R6112)). A record: the store
/// gives entries back whole.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct ContinuousEffect<L: Layout = Small> {
    /// The game index of the card the spell or ability that created it came from, as it was
    /// then. The source may since have left its zone, and once hidden its slot may hold another
    /// card ([CR 611.2a](https://yawgatog.com/resources/magic-rules/#R6112a): the effect lasts
    /// as stated even then), so the effect keeps the card rather than the slot.
    pub source: L::Card,
    /// When it began ([CR 613.7](https://yawgatog.com/resources/magic-rules/#R6137)): "An
    /// effect with an earlier timestamp is applied before an effect with a later timestamp."
    pub timestamp: u16,
    pub duration: Duration,
    pub affected: Affects<L>,
    pub payload: Payload,
}

/// An entry is 24 bytes in [`Small`], whichever side and payload it has: the store's room
/// (the crate's contract, "Stores") counts on it.
const _: () = assert!(size_of::<ContinuousEffect<Small>>() == 24);

impl<L: Layout> Default for ContinuousEffect<L> {
    fn default() -> Self {
        ContinuousEffect {
            source: L::Card::FIRST,
            timestamp: 0,
            duration: Duration::EndOfTurn,
            affected: Affects::object(ObjectRef::default()),
            payload: Payload::Move(MoveReplacement::ExileInsteadOfGraveyard),
        }
    }
}

/// The Effects store: the entries in the order they began, the sets of objects that
/// entries on several affect, and two indices of the entries, the kinds among them and the
/// rules they change for each player.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Effects<L: Layout = Small> {
    entries: L::Queue<ContinuousEffect<L>, EFFECTS>,
    /// The members of each set an entry names ([`Affects::Set`]).
    sets: Sets<L>,
    kinds: Kinds,
    /// The rules the entries on each player change, so that whether one applies to a
    /// player is one AND ([`State::rule_applies`]).
    rules: L::PerPlayer<Rules>,
}

impl Copy for Effects<Small> {}

/// The entries, and the members of each set one names: the kinds and the players' rules
/// are indices of them, and a hash of a state is a hash of the game.
impl<L: Layout> std::hash::Hash for Effects<L> {
    fn hash<H: std::hash::Hasher>(&self, h: &mut H) {
        self.entries.hash(h);
        for e in self.entries.iter() {
            if let Affects::Set(set) = e.affected {
                self.sets.members(set).hash(h);
            }
        }
    }
}

impl<L: Layout> Effects<L> {
    /// The entries, if one of them has a payload of a kind in `kinds`; none otherwise.
    #[inline]
    fn of(&self, kinds: u16) -> &[ContinuousEffect<L>] {
        if self.kinds.0 & kinds == 0 {
            return &[];
        }
        self.entries.as_slice()
    }

    /// Ends the entries `keep` refuses, and each whose set has no member left, and says
    /// what that changed.
    #[inline]
    fn end(&mut self, keep: impl Fn(&ContinuousEffect<L>) -> bool) -> Ended {
        let mut done = Ended::default();
        let mut kinds = 0;
        let mut rules: L::PerPlayer<Rules> = Table::filled(Rules::NONE);
        let sets = &mut self.sets;
        self.entries.retain(|e| {
            let mut kept = keep(e);
            if let Affects::Set(set) = e.affected {
                kept &= !sets.members(set).is_empty();
                if !kept {
                    sets.release(set);
                }
            }
            if kept {
                kinds |= e.payload.kind();
                if let Some((player, rule)) = e.player_rule() {
                    rules[player.index()] = rules[player.index()].with(rule);
                }
            } else {
                done.any = true;
                done.layer_input |= matches!(e.payload, Payload::Layer(_));
            }
            kept
        });
        self.sets.trim();
        self.kinds = Kinds(kinds);
        self.rules = rules;
        done
    }

    /// Whether an entry changes `rule` for exactly `affected`.
    #[inline]
    fn changes_rule(&self, rule: Rule, affected: Affects<L>) -> bool {
        self.of(Kinds::RULE)
            .iter()
            .any(|e| e.payload == Payload::Rule(rule) && e.affected == affected)
    }
}

impl<L: Layout> ContinuousEffect<L> {
    /// The player it changes a rule for and the rule, if that is what it does: what the
    /// store's index of the players' rules holds of it.
    #[inline]
    fn player_rule(&self) -> Option<(Seat, Rule)> {
        match (self.affected, self.payload) {
            (Affects::Player(player), Payload::Rule(rule)) => Some((player, rule)),
            _ => None,
        }
    }
}

impl<L: Layout> State<L> {
    /// Starts a continuous effect of the card `source`, with the next timestamp
    /// ([CR 611.2](https://yawgatog.com/resources/magic-rules/#R6112)): "A continuous effect
    /// may be generated by the resolution of a spell or ability."
    /// [CR 613.7](https://yawgatog.com/resources/magic-rules/#R6137): an effect's timestamp
    /// is the time it was created. An object it affects must be current, and a player is
    /// affected by a rule change alone. The layer results are stale from here if it changes
    /// a layer. No event: the rules announce what the effect is part of, as they do a
    /// change of control.
    ///
    /// # Panics
    ///
    /// For a locked-in set, which is another effect's:
    /// [`State::start_effect_on_set`] locks one in.
    #[inline]
    pub fn start_effect(
        &mut self,
        source: L::Card,
        affected: Affects<L>,
        payload: Payload,
        duration: Duration,
    ) -> Result<(), Full> {
        let timestamp = self.zones.next_timestamp;
        self.zones.next_timestamp = timestamp.wrapping_add(1);
        let pushed = self.effects.entries.push(ContinuousEffect {
            source,
            timestamp,
            duration,
            affected,
            payload,
        });
        if pushed.is_ok() {
            self.effects.kinds.0 |= payload.kind();
            match affected {
                Affects::Object { slot, incarnation } => {
                    debug_assert_eq!(self.object(slot).incarnation, incarnation);
                    self.keyed.insert(slot);
                }
                Affects::Player(player) => {
                    debug_assert!(matches!(payload, Payload::Rule(_)));
                    if let Payload::Rule(rule) = payload {
                        let rules = &mut self.effects.rules[player.index()];
                        *rules = rules.with(rule);
                    }
                }
                Affects::Set(_) => unreachable!("an effect on another effect's set"),
            }
        }
        if matches!(payload, Payload::Layer(_)) {
            self.flags.derived_dirty = true;
        }
        pushed
    }

    /// Every continuous effect, in the order they began: for tools, tests and a view. The
    /// rules ask by kind.
    #[inline]
    pub fn effects(&self) -> &[ContinuousEffect<L>] {
        self.effects.entries.as_slice()
    }

    /// The effects that change a permanent in a layer, each with its change, in the order
    /// they began. With none live, one AND.
    #[inline]
    pub fn layer_effects(&self) -> impl Iterator<Item = (&ContinuousEffect<L>, LayerChange)> {
        self.effects
            .of(Kinds::LAYER)
            .iter()
            .filter_map(|e| match e.payload {
                Payload::Layer(change) => Some((e, change)),
                _ => None,
            })
    }

    /// The replacements of where `object` goes. With none live on any object, one AND.
    #[inline]
    pub fn move_replacements(
        &self,
        object: ObjectRef<L>,
    ) -> impl Iterator<Item = MoveReplacement> + '_ {
        let affected = Affects::object(object);
        self.effects
            .of(Kinds::MOVE)
            .iter()
            .filter_map(move |e| match e.payload {
                Payload::Move(replacement) if e.affected == affected => Some(replacement),
                _ => None,
            })
    }

    /// The permissions to cast, in the order they began: who may cast which card from a
    /// zone it could not otherwise be cast from, and on what terms. Each names its card's
    /// current object (the store's invariant). With none live, one AND.
    #[inline]
    pub fn cast_permissions(&self) -> impl Iterator<Item = Permitted<L>> + '_ {
        self.effects.of(Kinds::CAST).iter().filter_map(|e| {
            match (e.payload, e.affected.as_object()) {
                (Payload::Cast(terms), Some(card)) => Some(Permitted {
                    card,
                    terms,
                    source: e.source,
                }),
                _ => None,
            }
        })
    }

    /// The generic mana the cost changes on the spell `object` add to its cost
    /// ([CR 601.2f](https://yawgatog.com/resources/magic-rules/#R6012f): "plus all additional
    /// costs and cost increases"). With no cost change live on any object, one AND.
    #[inline]
    pub fn cost_increase(&self, object: ObjectRef<L>) -> u8 {
        let affected = Affects::object(object);
        self.effects
            .of(Kinds::COST)
            .iter()
            .filter(|e| e.affected == affected)
            .fold(0, |total, e| match e.payload {
                Payload::Cost(CostChange::Increase(n)) => total.saturating_add(n),
                _ => total,
            })
    }

    /// The objects an effect that is no layer change is on: a card someone is permitted to
    /// cast, a spell with a cost change or a replacement of where it goes. A layer change
    /// shows in a permanent's layer results and these show nowhere on the object, so the
    /// rules treat none of them as interchangeable with another object
    /// ([`State::signature`]). With no such effect live, one AND.
    #[inline]
    pub fn told_apart_by_effects(&self) -> Bitboard<L::Slot> {
        self.effects
            .of(!Kinds::LAYER)
            .iter()
            .filter(|e| !matches!(e.payload, Payload::Layer(_)))
            .filter_map(|e| e.affected.as_object())
            .map(|r| r.slot)
            .collect()
    }

    /// The first permission to cast that a turn-start checkpoint would lose, in words
    /// ([`State::off_board`]): the words and the place in that list that saves hold for
    /// one, which name the player and the card and not what granted it.
    pub(crate) fn cast_permission_lingering(&self, t: &GameTable) -> Option<String> {
        let p = self.cast_permissions().next()?;
        Some(format!(
            "player {}'s permission to cast {}",
            p.terms.player.get(),
            t.def(self.card(p.card.slot)).name
        ))
    }

    /// The first rule change on a player that a turn-start checkpoint would lose, in words
    /// ([`State::off_board`]): the words and the place in that list that saves hold for
    /// one, which name the player and not the card it came from.
    pub(crate) fn rule_change_lingering(&self) -> Option<String> {
        self.effects.of(Kinds::RULE).iter().find_map(|e| {
            let (player, rule) = e.player_rule()?;
            let lasting = match e.duration {
                Duration::UntilYourNextTurn(theirs) if theirs == player => {
                    "until their next turn".to_owned()
                }
                other => other.words(),
            };
            Some(format!(
                "player {} {} {lasting}",
                player.get(),
                rule.words()
            ))
        })
    }

    /// Whether the change `rule` makes to the game's rules applies to `to` now, a player
    /// or a permanent, whoever makes it: a static ability of a permanent
    /// ([CR 604.1](https://yawgatog.com/resources/magic-rules/#R6041): "Static abilities do
    /// something all the time rather than being activated or triggered.") or the
    /// continuous effect of a resolved spell or ability
    /// ([CR 613.11](https://yawgatog.com/resources/magic-rules/#R61311): "Some continuous
    /// effects affect game rules rather than objects."). The one question the rules ask
    /// about a rule change.
    ///
    /// For a player it is one AND of two sets: the rules the permanents' static abilities
    /// change for them, which the layers found with control settled, and the rules the
    /// effects on them change, which this store keeps as they start and end. A permanent
    /// is asked for a rule about itself ([`Rule::whose`]): its copiable values answer for
    /// its own static abilities, which a face-down permanent has none of
    /// ([CR 708.2](https://yawgatog.com/resources/magic-rules/#R7082)), and the effects on
    /// it for the rest, one AND while no effect changes a rule.
    ///
    /// # Panics
    ///
    /// In debug builds, for a player while the layer results are stale.
    #[inline]
    pub fn rule_applies(&self, t: &GameTable, rule: Rule, to: Affects<L>) -> bool {
        match to {
            Affects::Player(player) => {
                debug_assert!(!self.flags.derived_dirty, "rules read while dirty");
                let i = player.index();
                self.static_rules[i]
                    .union(self.effects.rules[i])
                    .contains(rule)
            }
            Affects::Object { slot, .. } => {
                (rule.whose().is_none() && self.copiable(slot).has_rule(t, rule))
                    || self.effects.changes_rule(rule, to)
            }
            // A set is affected by a layer change alone.
            Affects::Set(_) => false,
        }
    }
}

impl<'a, L: Layout> Observation<'a, L> {
    /// The continuous effects, in the order they began. Every one is public: a spell or
    /// ability resolves in the open, and what it affects is an object every player sees or
    /// a slot, which is a public handle.
    pub fn effects(&self) -> &'a [ContinuousEffect<L>] {
        self.shown().effects()
    }

    /// Who may cast which card from a zone it could not otherwise be cast from, and on what
    /// terms: public, as the effects that grant them are. A card exiled until someone casts
    /// it is face up ([CR 406.3](https://yawgatog.com/resources/magic-rules/#R4063): "Exiled
    /// cards are, by default, kept face up and may be examined by any player at any time").
    pub fn cast_permissions(&self) -> impl Iterator<Item = Permitted<L>> + 'a {
        self.shown().cast_permissions()
    }
}

